package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class YearSixMentalConnectionsTest {
 private final List<String> ids=List.of(MentalPlaceCalculations.ADD,MentalPlaceCalculations.SUB,LargeMentalDecomposition.ADD,LargeMentalDecomposition.SUB,ConvenientNumberMental.ADD,ConvenientNumberMental.SUB,TwoStepChangeStories.ID,FactorPairMental.MENTAL);
 @Test public void yearSixFreshPublicAnswersBlankHelpAndEarlierBounds(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");Generator g=new Generator(new Random(195));Checker c=new Checker();for(String id:ids){assertTrue(GlobalCurriculum.pack(p).inGrade(id,6));assertTrue(GlobalCurriculum.pack(p).inGrade(id,5));List<String> recent=new ArrayList<>();CurriculumLimits six=GlobalCurriculum.limits(p.educationSystem,id,6),five=GlobalCurriculum.limits(p.educationSystem,id,5);for(int i=0;i<150;i++){Question q=g.next(id,recent,false,six);assertTrue(six.allows(q));assertTrue(five.allows(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());long answer;if(TwoStepChangeStories.supports(id)){int[] v=TwoStepChangeStories.read(q);answer=v[0]+(v[3]==1?v[1]:-v[1])+(v[4]==1?v[2]:-v[2]);}else if(FactorPairMental.supports(id)){Matcher m=Pattern.compile("^(\\d+) × (\\d+) × (\\d+)").matcher(q.prompt);assertTrue(m.find());answer=1;for(int j=1;j<=3;j++)answer*=Integer.parseInt(m.group(j));}else{Matcher m=Pattern.compile("^(\\d+) ([+−-]) (\\d+)").matcher(q.prompt);assertTrue(m.find());long a=Long.parseLong(m.group(1)),b=Long.parseLong(m.group(3));answer=m.group(2).equals("+")?a+b:a-b;}q.answers=new String[]{"poison"};q.expression="poison";assertTrue(c.check(q,List.of(),List.of(""+answer)).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(""+(answer+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertNotNull(h);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}}
  assertTrue(GlobalCurriculum.pack(p).inGrade("mixed",6));assertFalse(GlobalCurriculum.pack(p).inGrade(FactorPairMental.PAIRS,6));assertFalse(GlobalCurriculum.pack(p).inGrade(DoublingCalculation.MULTIPLY,6));
 }
 @Test public void sixDigitHelpChecksEachStudentSubtotalWithoutTransfer(){Question q=LargeMentalDecomposition.make(LargeMentalDecomposition.ADD,987654,123456);q.answers=new String[]{"poison"};HelpPlan h=HelpPlan.forQuestion(q);assertEquals(13,h.size());int step=0,running=987654;assertTrue(h.step(step++).accepts(""+running));for(int power=100000;power>=1;power/=10){int part=123456/power%10*power;assertTrue(h.step(step++).accepts(""+part));running+=part;assertTrue(h.step(step++).accepts(""+running));assertFalse(h.step(step-1).accepts(""+(running+1)));}assertEquals(1111110,running);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}
}
